approvedCommands:
python -c "
import yaml
rules = yaml.safe_load(open('countersign.yaml'))
required = {'id', 'requirement', 'priority', 'paths', 'ai_access'}
for r in rules:
    missing = required - set(r.keys())
    if missing:
        print('MISSING FIELDS in', r.get('id','?'), ':', missing)
    else:
        check_display = repr(r.get('check',''))[:40] if r.get('check') else '(UNVERIFIED)'
        print('OK', r['id'], r['ai_access'], check_display)
"

